class Solution:
    def evaluate(self, s: str, knowledge: List[List[str]]) -> str:
        kv = dict(knowledge)
        res = []
        i, n = 0, len(s)
        while i < n:
            if s[i] == '(':
                j = s.index(')', i)
                res.append(kv.get(s[i + 1:j], '?'))
                i = j + 1
            else:
                res.append(s[i])
                i += 1
        return ''.join(res)

