class Solution {
public:
    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> kv;
        for (auto& p : knowledge) kv[p[0]] = p[1];
        string res;
        int i = 0, n = s.size();
        while (i < n) {
            if (s[i] == '(') {
                int j = s.find(')', i);
                auto it = kv.find(s.substr(i + 1, j - i - 1));
                res += (it == kv.end()) ? "?" : it->second;
                i = j + 1;
            } else {
                res += s[i++];
            }
        }
        return res;
    }
};

