class Solution {
    public String evaluate(String s, List<List<String>> knowledge) {
        Map<String, String> kv = new HashMap<>();
        for (List<String> p : knowledge) kv.put(p.get(0), p.get(1));
        StringBuilder sb = new StringBuilder();
        int i = 0, n = s.length();
        while (i < n) {
            char c = s.charAt(i);
            if (c == '(') {
                int j = s.indexOf(')', i);
                sb.append(kv.getOrDefault(s.substring(i + 1, j), "?"));
                i = j + 1;
            } else {
                sb.append(c);
                i++;
            }
        }
        return sb.toString();
    }
}

