class Solution {
public:
    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> kv;
        for (auto& p : knowledge) kv[p[0]] = p[1];
        static const regex re("[(]([a-z]+)[)]");
        string res;
        size_t pos = 0;
        for (auto it = sregex_iterator(s.begin(), s.end(), re); it != sregex_iterator(); ++it) {
            auto& m = *it;
            res += s.substr(pos, m.position() - pos);
            auto f = kv.find(m[1].str());
            res += (f == kv.end()) ? string("?") : f->second;
            pos = m.position() + m.length();
        }
        res += s.substr(pos);
        return res;
    }
};

