class Solution {
    public String evaluate(String s, List<List<String>> knowledge) {
        Map<String, String> kv = new HashMap<>();
        for (List<String> p : knowledge) kv.put(p.get(0), p.get(1));
        Matcher m = Pattern.compile("[(]([a-z]+)[)]").matcher(s);
        StringBuilder sb = new StringBuilder();
        int pos = 0;
        while (m.find()) {
            sb.append(s, pos, m.start());
            sb.append(kv.getOrDefault(m.group(1), "?"));
            pos = m.end();
        }
        return sb.append(s.substring(pos)).toString();
    }
}

